-- 453_intake_xjz_warehouse_storage_csharp_evidence.sql
-- Purpose: ingest C# restored warehouse and item storage evidence without changing runtime restrictions yet.
-- Source pack: XJZ-csharp-evidence-capture-pack-20260818.zip

DROP TABLE IF EXISTS god2_research._xjz_stage_warehouse_kind_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_item_storage_rule;
DROP TABLE IF EXISTS god2_research._xjz_stage_warehouse_service_template;

CREATE TABLE god2_research._xjz_stage_warehouse_kind_template (
  warehouse_kind VARCHAR(64) PRIMARY KEY,
  display_name_zh_tw VARCHAR(128) NOT NULL,
  owner_kind VARCHAR(64) NOT NULL,
  npc_name_prefix_zh_tw VARCHAR(128) NOT NULL,
  npc_count INT NOT NULL,
  npc_index_min INT NULL,
  npc_index_max INT NULL,
  npc_indices_json LONGTEXT,
  npc_rom_paths_json LONGTEXT,
  runtime_table VARCHAR(128) NOT NULL,
  raw_source VARCHAR(255) NOT NULL,
  raw_line_min INT NULL,
  raw_line_max INT NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL,
  entry_resource_kind VARCHAR(64) NULL,
  entry_resource_id INT NULL,
  entry_resource_path VARCHAR(255) NULL,
  entry_enum_symbol VARCHAR(96) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_item_storage_rule (
  item_id INT PRIMARY KEY,
  item_code VARCHAR(64),
  item_prefix VARCHAR(32),
  name_zh_tw VARCHAR(160) NOT NULL,
  can_store_warehouse INT NULL,
  can_stack INT NULL,
  storage_source_column_zh_tw VARCHAR(128) NOT NULL,
  stack_source_column_zh_tw VARCHAR(128) NOT NULL,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_warehouse_service_template (
  service_id INT PRIMARY KEY,
  warehouse_kind VARCHAR(64) NOT NULL,
  display_name_zh_tw VARCHAR(128) NOT NULL,
  owner_kind VARCHAR(64) NOT NULL,
  supported_entity_kind VARCHAR(64) NOT NULL,
  runtime_table VARCHAR(128) NOT NULL,
  storage_rule_table VARCHAR(128) NULL,
  storage_rule_count INT NOT NULL,
  storable_item_count INT NOT NULL,
  stackable_item_count INT NOT NULL,
  npc_name_prefix_zh_tw VARCHAR(128) NOT NULL,
  npc_count INT NOT NULL,
  npc_index_min INT NULL,
  npc_index_max INT NULL,
  npc_indices_json LONGTEXT,
  npc_rom_paths_json LONGTEXT,
  entry_resource_kind VARCHAR(64) NULL,
  entry_resource_id INT NULL,
  entry_resource_path VARCHAR(255) NULL,
  entry_enum_symbol VARCHAR(96) NULL,
  raw_source VARCHAR(255) NOT NULL,
  raw_line_min INT NULL,
  raw_line_max INT NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS god2_research.xjz_warehouse_kind_evidence (
  warehouse_kind VARCHAR(64) NOT NULL,
  display_name_zh_tw VARCHAR(128) NOT NULL,
  owner_kind_zh_tw VARCHAR(64) NOT NULL,
  npc_name_prefix_zh_tw VARCHAR(128) NOT NULL,
  npc_count INT NOT NULL,
  npc_index_min INT NULL,
  npc_index_max INT NULL,
  npc_indices_zh_tw TEXT NOT NULL,
  npc_rom_paths_zh_tw TEXT NOT NULL,
  target_runtime_table_zh_tw VARCHAR(128) NOT NULL,
  entry_resource_kind_zh_tw VARCHAR(64) NULL,
  entry_resource_id INT NULL,
  entry_resource_path_zh_tw VARCHAR(255) NULL,
  entry_enum_symbol_zh_tw VARCHAR(96) NULL,
  source_line_min INT NULL,
  source_line_max INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (warehouse_kind)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：倉庫種類、NPC入口、流程入口與服務端目標表。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_item_storage_rule_evidence (
  item_id INT NOT NULL,
  item_code VARCHAR(64) NULL,
  item_prefix VARCHAR(32) NULL,
  item_name_zh_tw VARCHAR(160) NOT NULL,
  can_store_warehouse INT NULL,
  can_stack INT NULL,
  storage_rule_source_zh_tw VARCHAR(128) NOT NULL,
  stack_rule_source_zh_tw VARCHAR(128) NOT NULL,
  linked_formal_item_id BIGINT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (item_id),
  KEY ix_xjz_item_storage_linked_formal (linked_formal_item_id),
  KEY ix_xjz_item_storage_flags (can_store_warehouse, can_stack)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：道具是否可放倉庫、是否可堆疊候選規則。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_warehouse_service_evidence (
  service_id INT NOT NULL,
  warehouse_kind VARCHAR(64) NOT NULL,
  display_name_zh_tw VARCHAR(128) NOT NULL,
  owner_kind_zh_tw VARCHAR(64) NOT NULL,
  supported_entity_kind_zh_tw VARCHAR(64) NOT NULL,
  target_runtime_table_zh_tw VARCHAR(128) NOT NULL,
  storage_rule_table_zh_tw VARCHAR(128) NULL,
  storage_rule_count INT NOT NULL,
  storable_item_count INT NOT NULL,
  stackable_item_count INT NOT NULL,
  npc_name_prefix_zh_tw VARCHAR(128) NOT NULL,
  npc_count INT NOT NULL,
  entry_resource_kind_zh_tw VARCHAR(64) NULL,
  entry_resource_id INT NULL,
  entry_resource_path_zh_tw VARCHAR(255) NULL,
  entry_enum_symbol_zh_tw VARCHAR(96) NULL,
  source_line_min INT NULL,
  source_line_max INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (service_id),
  UNIQUE KEY ux_xjz_warehouse_service_kind (warehouse_kind)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：倉庫服務入口與服務端資料流。';

DELETE FROM god2_research.xjz_warehouse_kind_evidence;
SELECT
  warehouse_kind,
  display_name_zh_tw,
  CASE owner_kind WHEN 'character' THEN '角色' ELSE owner_kind END,
  npc_name_prefix_zh_tw,
  npc_count,
  npc_index_min,
  npc_index_max,
  npc_indices_json,
  npc_rom_paths_json,
  runtime_table,
  entry_resource_kind,
  entry_resource_id,
  entry_resource_path,
  entry_enum_symbol,
  raw_line_min,
  raw_line_max,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_warehouse_kind_template;

DELETE FROM god2_research.xjz_item_storage_rule_evidence;
SELECT
  s.item_id,
  s.item_code,
  s.item_prefix,
  s.name_zh_tw,
  s.can_store_warehouse,
  s.can_stack,
  REPLACE(REPLACE(s.storage_source_column_zh_tw, '是否放入倉庫', '是否可放入倉庫'), '是否放入仓库', '是否可放入倉庫'),
  REPLACE(REPLACE(s.stack_source_column_zh_tw, '是否堆棧', '是否可堆疊'), '是否堆栈', '是否可堆疊'),
  i.item_id,
  s.raw_line,
  s.evidence_status,
  s.packet_evidence_boundary
FROM god2_research._xjz_stage_item_storage_rule s
LEFT JOIN god2_game.items i ON i.client_item_id = s.item_id;

DELETE FROM god2_research.xjz_warehouse_service_evidence;
SELECT
  service_id,
  warehouse_kind,
  display_name_zh_tw,
  CASE owner_kind WHEN 'character' THEN '角色' ELSE owner_kind END,
  CASE supported_entity_kind WHEN 'item' THEN '道具' WHEN 'combat_pet' THEN '戰寵' ELSE supported_entity_kind END,
  runtime_table,
  storage_rule_table,
  storage_rule_count,
  storable_item_count,
  stackable_item_count,
  npc_name_prefix_zh_tw,
  npc_count,
  entry_resource_kind,
  entry_resource_id,
  entry_resource_path,
  entry_enum_symbol,
  raw_line_min,
  raw_line_max,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_warehouse_service_template;

CREATE OR REPLACE VIEW god2_research.vw_xjz_warehouse_storage_csharp_summary_zh_tw AS
SELECT '倉庫種類' AS 資料類型, COUNT(*) AS 筆數, NULL AS 可放倉庫, NULL AS 可堆疊, NULL AS 已連正式道具, SUM(needs_packet_evidence) AS 需要封包證據
FROM god2_research.xjz_warehouse_kind_evidence
UNION ALL
SELECT '道具存放規則', COUNT(*), SUM(CASE WHEN can_store_warehouse = 1 THEN 1 ELSE 0 END), SUM(CASE WHEN can_stack = 1 THEN 1 ELSE 0 END), SUM(CASE WHEN linked_formal_item_id IS NOT NULL THEN 1 ELSE 0 END), SUM(needs_packet_evidence)
FROM god2_research.xjz_item_storage_rule_evidence
UNION ALL
SELECT '倉庫服務入口', COUNT(*), SUM(storable_item_count), SUM(stackable_item_count), NULL, SUM(needs_packet_evidence)
FROM god2_research.xjz_warehouse_service_evidence;

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入倉庫服務與道具存放規則',
    safe_apply_level_zh_tw = '可用於服務端倉庫限制比對；正式限制需分批接 runtime',
    next_server_action_zh_tw = '比對現有背包與倉庫服務，先把已連正式道具的可存放與堆疊規則接成只讀檢查，再決定是否強制套用。',
    blocked_reason_zh_tw = '此批是客戶端規則證據，直接硬改 runtime 可能影響既有背包/倉庫行為。',
    related_project_object_zh_tw = 'migration 453, xjz_warehouse_*'
WHERE evidence_key = 'warehouse_storage_rules';

DROP TABLE IF EXISTS god2_research._xjz_stage_warehouse_kind_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_item_storage_rule;
DROP TABLE IF EXISTS god2_research._xjz_stage_warehouse_service_template;